import {requireSymbol} from '../../symbols/registry';
import type {SymbolPrimitive} from '../../symbols/types';
/** Synthetic, generated from current vector definitions/font, never private scan bytes. */
export function understandingFixture(kind:'ocr'|'symbols'|'unknown'|'rotated'|'photo'='ocr',width=960,height=640){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d')!;ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);const k=width/960;ctx.scale(k,k);ctx.strokeStyle='#222';ctx.fillStyle='#222';ctx.lineWidth=3;ctx.font='30px Arial';if(kind==='ocr'||kind==='rotated'||kind==='photo'){const labels=['ГАЗ','ВОДА','ТК-3','H=28.40','V-101','Ø57'];for(const [i,text]of labels.entries()){ctx.save();ctx.translate(70+(i%3)*280,65+Math.floor(i/3)*100);if(kind==='rotated')ctx.rotate(Math.PI/2);ctx.fillText(text,0,0);ctx.restore();}ctx.beginPath();ctx.moveTo(70,420);ctx.lineTo(500,420);ctx.moveTo(285,320);ctx.lineTo(285,500);ctx.stroke();}
else for(let i=0;i<4;i++){ctx.save();ctx.translate(130+(i%2)*320,140+Math.floor(i/2)*250);ctx.rotate(i%2*Math.PI/2);ctx.scale(70+(i%2)*15,-(70+(i%2)*15));ctx.lineWidth=3/(70+(i%2)*15);if(kind==='unknown'){ctx.beginPath();ctx.moveTo(-.4,-.4);ctx.lineTo(.4,-.4);ctx.lineTo(.4,.4);ctx.lineTo(-.4,.4);ctx.closePath();ctx.moveTo(-.4,-.4);ctx.lineTo(.4,.4);ctx.moveTo(-.4,.4);ctx.lineTo(.4,-.4);ctx.stroke();}else for(const p of requireSymbol('gas-process-demo','valve').geometry)draw(ctx,p);ctx.restore();}
if(kind==='photo'){const d=ctx.getImageData(0,0,width,height);for(let y=0;y<height;y++)for(let x=0;x<width;x++){const i=(y*width+x)*4,f=.5+.5*x/width;for(let c=0;c<3;c++)d.data[i+c]=Math.round((90+d.data[i+c]!*.6)*f);}ctx.putImageData(d,0,0);}return canvas;}
function draw(ctx:CanvasRenderingContext2D,p:SymbolPrimitive){ctx.beginPath();if(p.type==='circle')ctx.arc(p.center.x,p.center.y,p.radius,0,Math.PI*2);else if(p.type==='rect')ctx.rect(p.position.x,p.position.y,p.width,p.height);else{const points=p.type==='line'?[p.start,p.end]:p.points;points.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));if(p.type==='polygon')ctx.closePath();}ctx.stroke();}
